// @ts-check
// Generation script for src/shared/config/cache-version.gen.ts.
//
// CACHE_VERSION is derived from a content hash over every code that decides
// a KV payload's shape (server sources, parsers, config, cache infra, shared
// types). Editing any of it changes the hash -> the version flips -> the
// cache hard-cuts to fresh keys on the next deploy. Comments, formatting and
// unrelated code (UI, client, workers) are normalized out of the hash, so
// they never trigger a pointless generation change.
//
// The generated file is committed (like worker-configuration.d.ts) so fresh
// clones and type-check see a stable value without running the script; the
// hash only changes when the inputs do. Run manually: `npm run
// gen:cache-version`. Wired into `postinstall` (fresh clones) and the head
// of `check` (every build/deploy/CI path) via package.json.
const fs = require("fs");
const path = require("path");
const { walkTs, stripComments } = require("./_util.cjs");

const ROOT = path.join(__dirname, "..");
const OUT = path.join(ROOT, "src", "shared", "config", "cache-version.gen.ts");

/** Code dirs that decide payload shapes, relative to ROOT. */
const HASH_INPUT_DIRS = [
  path.join(ROOT, "src", "server", "sources"),
  path.join(ROOT, "src", "server", "parsers"),
  path.join(ROOT, "src", "server", "config"),
  path.join(ROOT, "src", "server", "infra"),
  path.join(ROOT, "src", "server", "context.ts"),
  path.join(ROOT, "src", "shared", "types"),
  path.join(ROOT, "src", "shared", "config"),
  path.join(ROOT, "src", "shared", "utils"),
];

const GEN_HEADER = `// Generated by scripts/gen-cache-version.cjs — do not edit.
// Changes whenever code that decides KV payload shapes changes (see the script
// header for the hashed inputs). Committing it keeps fresh clones and
// type-check stable, and makes cache-generation flips visible in PR diffs.
`;

function collectFiles() {
  const files = [];
  for (const input of HASH_INPUT_DIRS) {
    if (fs.statSync(input).isFile()) {
      files.push(input);
      continue;
    }
    files.push(...walkTs(input));
  }
  return [...new Set(files)]
    .filter((f) => f !== OUT) // the output must not feed its own hash
    .sort();
}

function hashFiles() {
  // eslint-disable-next-line global-require
  const { createHash } = require("crypto");
  const hash = createHash("sha256");
  for (const file of collectFiles()) {
    hash.update(path.relative(ROOT, file).replaceAll("\\", "/"));
    hash.update("\0");
    // Comments keep their line breaks after stripping, so collapse all
    // whitespace: comment edits and reformats must not flip the generation.
    hash.update(stripComments(fs.readFileSync(file, "utf8")).replace(/\s+/g, " "));
    hash.update("\0");
  }
  return hash.digest("hex").slice(0, 12);
}

function main() {
  const version = `sha-${hashFiles()}`;
  const content = `${GEN_HEADER}export const CACHE_VERSION = "${version}";\n`;
  const existing = fs.existsSync(OUT) ? fs.readFileSync(OUT, "utf8") : "";
  if (existing === content) {
    console.log(`gen:cache-version ok (${version})`);
    return;
  }
  fs.writeFileSync(OUT, content);
  console.log(`gen:cache-version updated (${version})`);
}

main();
